"""Plain-text absence notices for parents."""

from datetime import date
from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice naming the student and the days absent."""
    entries = list(marks)
    _check_owner(student, entries)
    days = _absent_days(entries)
    return _format_notice(student, days)

def _check_owner(
    student: Student, marks: List[Mark]
) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for other student {mark.student_id}"
            )

def _absent_days(marks: List[Mark]) -> List[date]:
    """Distinct absent days, oldest first."""
    days = sorted(set(days_missed(marks)))
    if not days:
        raise ValueError("no absences to report")
    return days

def _format_notice(
    student: Student, days: List[date]
) -> str:
    name = f"{student.first_name} {student.last_name}"
    count = len(days)
    noun = "day" if count == 1 else "days"
    dates = ", ".join(item.isoformat() for item in days)
    return f"{name} was absent on {count} {noun}: {dates}."
